type Category = "Cachorros" | "Gatos" | "Farmácia" | "Aves" | "Casa & Jardim" | "Diversos" | "Higiene" | "Roedores";
type ProductVariant = { id: number; label: string; price: number; oldPrice?: number; stock: number };
type ProductImage = { id: number; url: string; alt?: string; sortOrder: number; isCover: boolean };
type Product = {
  id: number;
  slug: string;
  name: string;
  category: Category;
  subcategory: string;
  price: number;
  oldPrice?: number;
  stock: number;
  rating: number;
  reviews: number;
  badge?: string;
  emoji: string;
  description: string;
  variant?: string;
  specs: [string, string][];
  image?: string;
  images: ProductImage[];
  variants: ProductVariant[];
};
type CartItem = { productId: number; quantity: number; variant?: string };

function mapCatalogProduct(row: any): Product {
  const variants = (row.variants || []).map((variant: any) => ({ id: variant.id, label: variant.label, price: Number(variant.price || 0), oldPrice: variant.oldPrice ? Number(variant.oldPrice) : undefined, stock: Number(variant.stock || 0) }));
  const images = (row.images || []).sort((a: any, b: any) => a.sortOrder - b.sortOrder);
  const variant = variants[0]; const cover = images.find((image: any) => image.isCover) || images[0];
  return { id: row.id, slug: row.slug, name: row.name, category: row.category as Category, subcategory: row.subcategory, price: variant?.price || 0, oldPrice: variant?.oldPrice, stock: variant?.stock || 0, rating: 5, reviews: 0, badge: row.status === "active" ? undefined : "Indisponível", emoji: "🐾", description: row.description || "Produto selecionado para a rotina do seu pet.", variant: variant?.label || "Tamanho único", specs: (row.specs || []).map((spec: any) => [spec.label, spec.value] as [string, string]), image: cover?.url, images, variants };
}

